def interleave_lists(lists):
    result = []
    idx = 0
    while True:
        any_taken = False
        for lst in lists:
            if idx < len(lst):
                result.append(lst[idx])
                any_taken = True
        if not any_taken:
            break
        idx += 1
    return result
